//! Template plugin: renames one configured playlist group in `playlist.after-filter`.
//!
//! Settings come from `config-schema.json`:
//! - `rename_from`: the exact group name to match. Empty disables the rename.
//! - `rename_to`: the new group name.
//! - `api_token`: a write-only secret. The host masks it when the settings are
//!   read back and redacts it from logs. This template never reads it; it only
//!   shows how a secret is declared. Never log a secret yourself.
//!
//! The default `lifecycle` (generated by `#[tuliprox_plugin]`) parses `Settings`
//! at init, so a bad configuration disables the instance with the parse error.

use tuliprox_plugin_sdk::prelude::*;

#[tuliprox_plugin]
mod plugin {
    use super::*;

    #[tuliprox_plugin_settings]
    pub struct Settings {
        #[serde(default)]
        pub rename_from: String,
        #[serde(default)]
        pub rename_to: String,
        // Declared so the settings schema and the typed struct agree. This template
        // never reads it; a real plugin passes it to its HTTP client via `expose()`.
        #[allow(dead_code)]
        pub api_token: Option<Secret<String>>,
    }

    pub struct Rename;

    impl PlaylistHooks for Rename {
        fn on_stage(stage: Stage, _target: &str, channels: Vec<Channel>) -> Result<Vec<ChannelChange>, String> {
            // The manifest lists only playlist.after-filter. The host may still pass
            // other stages of this interface, so ignore them.
            if !matches!(stage, Stage::AfterFilter) {
                return Ok(Vec::new());
            }
            let settings = Settings::current()?;
            if settings.rename_from.is_empty() || settings.rename_from == settings.rename_to {
                return Ok(Vec::new());
            }
            // Return only the channels that changed, as `modified` entries.
            Ok(channels
                .into_iter()
                .filter(|channel| channel.group == settings.rename_from)
                .map(|mut channel| {
                    channel.group.clone_from(&settings.rename_to);
                    ChannelChange::Modified(channel)
                })
                .collect())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tuliprox_plugin_sdk::mock;

    fn channel(handle: u32, group: &str) -> Channel {
        Channel {
            handle,
            name: format!("ch{handle}"),
            title: String::new(),
            group: group.to_string(),
            url: String::new(),
            epg_id: None,
            logo: String::new(),
            chno: None,
            item_type: ItemType::Live,
            cluster: Cluster::Live,
            input_name: "in".to_string(),
            input_stream_id: handle.to_string(),
            extra: Vec::new(),
        }
    }

    #[test]
    fn renames_only_the_configured_group_after_filter() {
        mock::reset();
        mock::set_config(r#"{"rename_from":"News","rename_to":"Plugin News","api_token":"s3cret"}"#);
        // The default lifecycle caches settings at init; a unit test has no init, so reload.
        plugin::Settings::reload().unwrap();

        let changes = <plugin::Rename as PlaylistHooks>::on_stage(
            Stage::AfterFilter,
            "main",
            vec![channel(1, "News"), channel(2, "Sport")],
        )
        .unwrap();

        assert_eq!(changes.len(), 1);
        let ChannelChange::Modified(renamed) = &changes[0] else {
            panic!("expected a modified channel");
        };
        assert_eq!(renamed.handle, 1);
        assert_eq!(renamed.group, "Plugin News");
    }
}
